response_html:
Hello <b>{{frappe.db.get_value("Job Applicant",doc.job_applicant,"applicant_name")}}</b><br>
<p>We are pleased to let you know that you have been scheduled an interview. This is in reference to the <b>{{doc.designation}}</b> position from {{frappe.db.get_value("Job Opening",doc.job_opening,"company")}}.</p>
<p>The interview details are as follows:</p>
<hr>
Interview Name : <b>{{doc.name}}</b><br>
{% if doc.interview_round == "Zoom"%}
Zoom Link : <a href="{{doc.custom_zoom_link}}"></a><br>
Zoom Password : {{doc.custom_zoom_password}}<br>
{% endif %}
{% set get_datetime = frappe.utils.get_datetime %}
{% set formatdate = frappe.utils.formatdate %}
{% set format_time = frappe.utils.format_time %}
{% set scheduled_date = formatdate(get_datetime(doc.scheduled_on), "MMMM dd, yyyy") %}
{% set from_time = format_time(get_datetime(doc.from_time), "hh:mm a") %}
Interview Date & Time: {{ scheduled_date }} {{ from_time }}<br>
Interviewer : {{doc.interview_details | map(attribute="interviewer") | join(', ') }}<br>
Hr Manager: {{frappe.db.get_value("User",frappe.db.get_value("Job Requisition",frappe.db.get_value("Job Opening",doc.job_opening,"job_requisition"),"custom_assign_to_recruiter"),"full_name")}}<br>
<p>Kindly mark your presence 10 minutes prior to the interview time.<br>
Thanks in advance.
</p>

Hello Sir/Madam,<br>
<p>This is to notify that you have been scheduled to conduct an interview session for <b>{{frappe.db.get_value("Job Applicant",doc.job_applicant,"applicant_name")}}</b>
for the position of <b>{{doc.designation}}</b>. </p>
<p>The interview details are as follows: </p>
<hr>
Company : {{frappe.db.get_value("Job Opening",doc.job_opening,"company")}}<br>
Interview Type : {{doc.interview_round}}<br>
{% set get_datetime = frappe.utils.get_datetime %}
{% set formatdate = frappe.utils.formatdate %}
{% set format_time = frappe.utils.format_time %}
{% set scheduled_date = formatdate(get_datetime(doc.scheduled_on), "MMMM dd, yyyy") %}
{% set from_time = format_time(get_datetime(doc.from_time), "hh:mm a") %}
Interview Date & Time: {{ scheduled_date }} {{ from_time }}<br>
Department Name : {{frappe.db.get_value("Job Opening",doc.job_opening,"department")}}<br>
Hr Manager: {{frappe.db.get_value("User",frappe.db.get_value("Job Requisition",frappe.db.get_value("Job Opening",doc.job_opening,"job_requisition"),"custom_assign_to_recruiter"),"full_name")}}<br>
{% if doc.interview_round == "Zoom"%}
Zoom Link : <a href="{{doc.custom_zoom_link}}"></a><br>
Zoom Password : {{doc.custom_zoom_password}}<br>
{% endif %}
<p>Please be sure to complete assessment comment on how the interview went on, using the button below. </p>
<a href="/app/interview-feedback?interview=doc.name">Link to submit Feedback</a><br>
<p>Regards,</p><br>
{{frappe.db.get_value("Job Opening",doc.job_opening,"company")}} Team
